// Müşteri mesajını al ve normalize et (Türkçe karakterlere duyarlı)
const raw = String($input.first().json.chatInput || "");
const message = raw.toLocaleLowerCase("tr-TR").replace(/\s+/g, " ").trim();
const has = (list) => list.some((w) => message.includes(w));

// Ürün adı anahtar kelimeleri (ürün detayları "Urun Destek Cevabi" düğümündedir)
const productKeys = {
  "Bluetooth Kulaklık": ["bluetooth", "kulaklık", "kulaklik", "kulaklığ"],
  "Kablosuz Mouse": ["kablosuz mouse", "mouse"],
  "Mekanik Klavye": ["mekanik klavye", "klavye"]
};
const mentioned = Object.keys(productKeys).filter((name) => productKeys[name].some((k) => message.includes(k)));

// Kelime listeleri
const listWords = ["ürünler", "urunler", "ürün listesi", "katalog", "stokta", "hangi ürün", "neler var", "mevcut"];
const compareWords = ["karşılaştır", "karsilastir", "kıyasla", "kiyasla", "hangisi"];
const promoWords = ["kampanya", "indirim", "promosyon", "fırsat", "kupon"];
const hoursWords = ["çalışma saat", "calisma saat", "mesai", "kaçta açıl", "kaçta kapan", "açık mı", "saatleri", "hafta sonu", "mağaza"];
const deliveryWords = ["teslimat", "teslim süresi", "kaç günde", "kac gunde", "ne zaman gelir", "kargo ücreti", "kargo ucreti", "ücretsiz kargo"];
const contactWords = ["iletişim", "iletisim", "telefon numar", "adres", "e-posta", "eposta", "mail adres", "nasıl ulaş", "nasil ulas"];
const complaintWords = ["şikayet", "sikayet", "şikâyet", "memnun değil", "memnun degil", "bozuk", "bozul", "çalışmıyor", "calismiyor", "çalışmadı", "arıza", "ariza", "sorun", "problem", "hata", "bağlanmıyor", "baglanmiyor", "şarj olmuyor", "açılmıyor", "acilmiyor", "tepki vermiyor", "kırık", "kirik", "gelmedi", "yanlış ürün", "teknik destek"];
const strongTopic = ["iade", "garanti", "temsilci"].find((k) => message.includes(k));

// Bütçe: sayı + bütçe ifadesi (ör. "bütçem 1.000 TL", "800 lira altı", "1 bin")
let budget = null;
const cleaned = message.replace(/(\d)\.(\d{3})/g, "$1$2");
const numMatch = cleaned.match(/(\d+)\s*(bin(?![a-zçğıöşü])|k(?![a-zçğıöşü]))?/);
const budgetWords = ["bütçe", "butce", "tl", "lira", "₺", "öner", "oner", "altında", "altinda", "altı", "en fazla", "kadar", "civarı", "param"];
if (numMatch && has(budgetWords)) {
  const value = parseInt(numMatch[1], 10) * (numMatch[2] ? 1000 : 1);
  if (value > 0) budget = value;
}

// Sipariş numarası (NT1234)
const orderMatch = message.match(/(^|[^a-zçğıöşü])nt[\s-]?(\d{4})/);
const orderId = orderMatch ? "NT" + orderMatch[2] : null;

// Açık destek kaydı isteği (yalnızca açıkça talep edilirse; sıradan teknik sorular kayıt açmaz)
const ticketWords = ["destek talebi oluştur", "destek talebi olustur", "destek talebi aç", "destek talebi ac", "destek kaydı oluştur", "destek kaydi olustur", "destek kaydı aç", "destek kaydi ac", "şikayet kaydı oluştur", "şikayet kaydı aç", "şikâyet kaydı oluştur", "şikâyet kaydı aç", "sikayet kaydi olustur", "sikayet kaydi ac", "arıza kaydı oluştur", "arıza kaydı aç", "ariza kaydi olustur", "ariza kaydi ac", "talep oluştur", "talep olustur", "talebi oluştur", "talebi olustur", "kayıt oluştur", "kayit olustur", "kayıt aç", "kayit ac"];

// Niyet seçimi (öncelik sırası yukarıdan aşağıya)
let intent = "karsilama";
let topic = "karsilama";
// Destek kaydı durum sorgusu: NVT-00001 gibi referanstan sayısal id çıkarılır
const refMatch = message.match(/nvt[\s-]*(\d{1,9})/);
const ticketId = refMatch ? parseInt(refMatch[1], 10) : null;
const queryWords = ["durumu", "durumunu", "sorgula", "sorgu", "ne durumda", "nasıl gitti", "ne oldu", "takip"];
const ticketNouns = ["talep", "kayıt", "kayit", "destek", "ticket", "nvt"];
const isTicketQuery = !has(ticketWords) && ((ticketId !== null && !orderId) || (has(queryWords) && has(ticketNouns) && !has(["sipariş", "siparis", "kargo"])));

if (isTicketQuery) { intent = "destek_sorgula"; topic = "sorgu"; }
else if (has(ticketWords)) { intent = "destek_kaydi"; topic = "kayit"; }
else if (orderId) { intent = "siparis"; topic = "durum"; }
else if (!message.includes("temsilci") && has(complaintWords)) { intent = "destek"; topic = "sikayet"; }
else if (mentioned.length >= 2) { intent = "urun"; topic = "karsilastir"; }
else if (has(compareWords)) { intent = "urun"; topic = "karsilastir_eksik"; }
else if (budget !== null && mentioned.length === 0) { intent = "urun"; topic = "butce"; }
else if (mentioned.length === 0 && has(promoWords)) { intent = "urun"; topic = "kampanya"; }
else if (has(hoursWords)) { intent = "destek"; topic = "saat"; }
else if (has(deliveryWords)) { intent = "destek"; topic = "teslimat"; }
else if (has(contactWords)) { intent = "destek"; topic = "iletisim"; }
else if (strongTopic) { intent = "destek"; topic = strongTopic; }
else if (mentioned.length > 0) { intent = "urun"; topic = "tekil"; }
else if (has(listWords)) { intent = "urun"; topic = "liste"; }
else if (message.includes("kargo")) { intent = "destek"; topic = "kargo"; }
else if (has(["sipariş", "siparis"])) { intent = "siparis"; topic = "genel"; }
else if (message.includes("fiyat")) { intent = "urun"; topic = "fiyat"; }

return [{ json: { chatInput: raw, message, intent, topic, orderId, budget, products: mentioned, ticketId } }];

const { topic, message, budget, products } = $input.first().json;

// Ürün kataloğu (sabit, kurgusal liste). discount: DEMO kampanya indirimi (%)
const catalog = [
  { name: "Bluetooth Kulaklık", price: "750 TL", priceNum: 750, inStock: true, discount: 10, detail: "Bluetooth (kablosuz) bağlantılı kulaklık" },
  { name: "Kablosuz Mouse", price: "450 TL", priceNum: 450, inStock: true, discount: 20, detail: "Kablosuz bağlantılı mouse" },
  { name: "Mekanik Klavye", price: "1.200 TL", priceNum: 1200, inStock: false, discount: 15, detail: "Mekanik tuşlu klavye" }
];

const fiyatSorusu = "💰 Fiyat bilgisi için size yardımcı olmak isterim. Hangi ürünle ilgileniyorsunuz? (Örneğin: Bluetooth Kulaklık, Kablosuz Mouse, Mekanik Klavye)";

const stockText = (p) => (p.inStock ? "✅ Stokta var" : "❌ Şu anda stokta yok");
const fmt = (n) => String(n).replace(/\B(?=(\d{3})+(?!\d))/g, ".") + " TL";
const promoPrice = (p) => Math.round(p.priceNum * (100 - p.discount) / 100);
const promoLine = (p) => "🏷️ DEMO kampanya: %" + p.discount + " indirimle " + fmt(promoPrice(p));

const mentioned = catalog.filter((p) => products.includes(p.name));
const product = mentioned[0];

let output = "";
if (topic === "karsilastir") {
  output = "⚖️ Ürün karşılaştırması\n\n" +
    mentioned.map((p, i) =>
      (i + 1) + ") " + p.name + "\n   Fiyat: " + p.price + "\n   Durum: " + stockText(p) +
      "\n   Bilinen özellik: " + p.detail + "\n   " + promoLine(p)
    ).join("\n\n") +
    (mentioned.length === 2 ? "\n\nFiyat farkı: " + fmt(Math.abs(mentioned[0].priceNum - mentioned[1].priceNum)) + "." : "") +
    "\n\nNot: Demo kataloğumuzda bunların dışında teknik özellik bilgisi bulunmuyor.";
} else if (topic === "karsilastir_eksik") {
  output = "⚖️ Karşılaştırma için iki ürün adını tek mesajda yazın. Örneğin: Kablosuz Mouse ile Mekanik Klavye karşılaştır.\n\nÜrünlerimiz: " +
    catalog.map((p) => p.name).join(", ") + ".";
} else if (topic === "butce") {
  const affordable = catalog.filter((p) => p.priceNum <= budget);
  const available = affordable.filter((p) => p.inStock);
  if (available.length > 0) {
    const unavailable = affordable.filter((p) => !p.inStock);
    output = "🎯 " + fmt(budget) + " bütçenize uygun ürünler:\n\n" +
      available.map((p) => "• " + p.name + " - " + p.price + " - " + stockText(p)).join("\n") +
      (unavailable.length > 0 ? "\n\nℹ️ Bütçenize uyan ama şu an stokta olmayan: " + unavailable.map((p) => p.name).join(", ") + "." : "") +
      "\n\nDEMO kampanyalar için 'kampanya' yazabilirsiniz.";
  } else {
    const cheapest = catalog.reduce((a, b) => (a.priceNum <= b.priceNum ? a : b));
    output = "🙏 " + fmt(budget) + " bütçesine uygun bir ürün kataloğumuzda yok. En uygun fiyatlı ürünümüz: " +
      cheapest.name + " (" + cheapest.price + ").";
  }
} else if (topic === "kampanya") {
  output = "🏷️ DEMO kampanyalar\n\n" +
    catalog.map((p) => "• " + p.name + ": " + p.price + " → " + fmt(promoPrice(p)) + " (%" + p.discount + " indirim) - " + stockText(p)).join("\n") +
    "\n\n⚠️ Bu kampanyalar eğitim amaçlı kurgusal DEMO verisidir; gerçek bir indirim değildir.";
} else if (topic === "tekil" && product) {
  output = "🛒 " + product.name + "\nFiyat: " + product.price + "\nDurum: " + stockText(product) + "\n" + promoLine(product);
  if (budget !== null && product.priceNum > budget) {
    output += "\n\nℹ️ Not: Bu ürün belirttiğiniz " + fmt(budget) + " bütçenin üzerinde.";
  }
  if (message.includes("kargo")) {
    output += "\n\n📦 Kargo bilgisi için sadece 'kargo' yazmanız yeterli.";
  }
} else if (topic === "liste") {
  output = "📋 NovaTech ürün listesi:\n\n" +
    catalog.map((p) => "• " + p.name + " - " + p.price + " - " + stockText(p)).join("\n") +
    "\n\nBir ürünün adını yazarak fiyat ve stok bilgisini öğrenebilirsiniz.";
} else {
  output = fiyatSorusu;
}

return [{ json: { output } }];

const { topic, orderId } = $input.first().json;

// DEMO siparişler (yalnızca durum bilgisi)
const orders = {
  NT1001: "Hazırlanıyor 🛠️",
  NT1002: "Kargoya verildi 🚚",
  NT1003: "Teslim edildi ✅"
};

let output = "";
if (topic === "durum" && orders[orderId]) {
  output = "📦 DEMO sipariş durumu\n\nSipariş: " + orderId + "\nDurum: " + orders[orderId] +
    "\n\n⚠️ Bu, eğitim amaçlı DEMO örnek verisidir. Gerçek bir sipariş sorgulanmadı.";
} else if (topic === "durum") {
  output = "🔎 " + orderId + " numaralı sipariş DEMO listesinde yok.\n\nDeneyebileceğiniz DEMO sipariş numaraları:\n" +
    "• NT1001 (hazırlanıyor)\n• NT1002 (kargoya verildi)\n• NT1003 (teslim edildi)\n\n" +
    "⚠️ Bunlar kurgusal örneklerdir; gerçek sipariş sorgulanmaz.";
} else {
  output = "📦 Sipariş durumu için DEMO sipariş numarasını tek mesajda yazın: NT1001, NT1002 veya NT1003.\n\n" +
    "⚠️ Bunlar kurgusal örneklerdir; gerçek sipariş sorgulanmaz. Gerçek kargo takibi adımları için 'kargo' yazabilirsiniz.";
}

return [{ json: { output } }];

const { topic, products } = $input.first().json;

// Hazır cevaplar
const replies = {
  kargo: "📦 Kargo takibi (DEMO): Bu örnek sistem gerçek kargo şirketlerine bağlı değildir. Gerçek bir alışverişte satıcının verdiği takip numarasıyla ilgili kargo firmasının resmî sitesinden gönderiyi sorgulayabilirsiniz.",
  iade: "↩️ İade (DEMO): Bu uygulama gerçek iade kodu oluşturmaz veya para iadesi başlatmaz. İade koşulları işletmeye, ürüne ve yürürlükteki mevzuata göre değişebilir. Burada örnek bir destek kaydı oluşturabilirsiniz.",
  garanti: "🛡️ Garanti (DEMO): Bu sistem garanti süresi veya kapsamını doğrulamaz. Gerçek bir ürün için fatura, garanti belgesi ve satıcının resmî koşullarını inceleyin. Sorununuzu kaydetmek için destek talebi oluşturabilirsiniz.",
  temsilci: "👤 Talebiniz için bir insan destek temsilcisine ihtiyaç var. Bu DEMO bot bir temsilciye bildirim göndermez ve görüşme başlatmaz. Gerçek destek için işletmenin resmî iletişim kanalını kullanın."
};

// Ürüne özel basit sorun giderme adımları
const tips = {
  "Bluetooth Kulaklık": "• Kulaklığı şarj edip kapatıp yeniden açın.\n• Telefonunuzun Bluetooth listesinden kulaklığı silip yeniden eşleştirin.\n• Başka bir cihazla eşleştirmeyi deneyin.",
  "Kablosuz Mouse": "• Pilini kontrol edin veya yenisiyle değiştirin.\n• Alıcıyı başka bir USB girişine takın.\n• Mouse'u kapatıp yeniden açın ve farklı bir yüzeyde deneyin.",
  "Mekanik Klavye": "• Kabloyu çıkarıp başka bir USB girişine takın.\n• Klavyeyi başka bir bilgisayarda deneyin.\n• Tuşların arasında toz veya kir olup olmadığına bakın."
};
const generic = "• Cihazı kapatıp yeniden açın.\n• Kablo, pil veya şarj bağlantısını kontrol edin.\n• Mümkünse cihazı başka bir bilgisayar/telefonla deneyin.";

let output = "";
if (topic === "sikayet") {
  const productName = products.length > 0 ? products[0] : null;
  const steps = productName ? tips[productName] : generic;
  output = "😔 Yaşadığınız sorun için üzgünüz, yardımcı olmaya çalışalım." +
    (productName ? "\n\nÜrün: " + productName : "") +
    "\n\nŞunları deneyebilirsiniz:\n" + steps +
    "\n• Cihazda sıvı teması, kırık veya yanık kokusu varsa kullanmayı bırakın.\n\n" +
    "Sorun devam ederse garanti bilgisi için 'garanti', insan destek temsilcisi bilgisi için 'temsilci' yazabilirsiniz.\n\n" +
    "⚠️ Not: Bu mesaj otomatik olarak destek talebi oluşturmaz ve kimseye bildirim göndermez. Kayıt açmak isterseniz 'destek talebi oluştur' yazabilirsiniz.";
} else if (topic === "saat") {
  output = "🕘 DEMO mağaza saatleri\n\nHafta içi: 09:00 - 18:00\nCumartesi: 10:00 - 16:00\nPazar: Kapalı\n\n" +
    "⚠️ NovaTech kurgusal bir demo mağazadır; bu saatler örnek amaçlıdır.";
} else if (topic === "teslimat") {
  output = "🚚 DEMO teslimat bilgisi\n\n• Tahmini teslimat: 1-3 iş günü\n• 1.500 TL üzeri siparişlerde ücretsiz kargo\n• 1.500 TL altı siparişlerde 49 TL kargo ücreti\n\n" +
    "⚠️ Bunlar kurgusal demo bilgileridir, gerçek bir teslimat taahhüdü değildir. Sipariş takibi için 'kargo' yazabilirsiniz.";
} else if (topic === "iletisim") {
  output = "📞 DEMO iletişim bilgisi\n\nNovaTech kurgusal bir demo mağazadır, bu yüzden gerçek bir telefon, adres veya e-posta bilgisi yoktur.\n\n" +
    "Örnek (gerçek değil): destek@novatech.example\n\nİnsan destek temsilcisi bilgisi için 'temsilci' yazabilirsiniz.";
} else if (replies[topic]) {
  output = replies[topic];
} else {
  output = replies.kargo;
}

return [{ json: { output } }];

// Data Table'a yazılacak alanları hazırlar (müşterinin ORİJİNAL mesajı saklanır)
const original = String($input.first().json.chatInput || "").trim().slice(0, 1000);
const text = original.toLocaleLowerCase("tr-TR");
const has = (list) => list.some((w) => text.includes(w));

// 1) Kural listeleri (yapay zeka YOK; yalnızca anahtar kelime kuralları)
const safetyWords = ["duman", "şiş", "sis pil", "patla", "yangın", "yangin", "alev", "kıvılcım", "kivilcim", "yanık", "yanik", "yanıyor", "yaniyor", "yandı", "aşırı ısın", "asiri isin", "çok ısın", "eridi", "erimiş"];
const refundWords = ["iade", "geri öde", "geri ode", "para iadesi", "ücret iadesi", "ucret iadesi"];
const warrantyWords = ["garanti"];
const shippingWords = ["kargo", "kurye", "teslimat", "gelmedi", "ulaşmadı", "ulasmadi", "teslim edilmedi"];
const defectWords = ["bozuk", "bozul", "çalışmıyor", "calismiyor", "çalışmadı", "calismadi", "arıza", "ariza", "açılmıyor", "acilmiyor", "şarj olmuyor", "sarj olmuyor", "bağlanmıyor", "baglanmiyor", "tepki vermiyor", "kırık", "kirik", "sorun", "problem", "hatalı", "hatali"];
const deliveryFailWords = ["gelmedi", "ulaşmadı", "ulasmadi", "teslim edilmedi", "kayıp", "kayip", "kaybol", "hasarlı", "hasarli", "geç kaldı", "gec kaldi", "gecikti", "gecikme", "eksik"];

// 2) Kategori (öncelik sırası: iade > garanti > kargo > teknik_destek > genel)
const isSafety = has(safetyWords);
let category = "genel";
if (has(refundWords)) category = "iade";
else if (has(warrantyWords)) category = "garanti";
else if (has(shippingWords)) category = "kargo";
else if (has(defectWords) || isSafety) category = "teknik_destek";

// 3) Öncelik
let priority = "Normal";
if (isSafety) priority = "Yuksek";
else if (category === "teknik_destek" || (category === "kargo" && has(deliveryFailWords)) || (category === "garanti" && has(defectWords))) priority = "Orta";

// 4) Konu: yalnızca mesajda GERÇEKTEN geçen ürün adı ve sipariş numarası kullanılır
const productLabels = [["Kulaklık", ["kulaklık", "kulaklik"]], ["Mouse", ["mouse"]], ["Klavye", ["klavye"]]];
const found = productLabels.filter((p) => p[1].some((k) => text.includes(k))).map((p) => p[0]);
const orderMatch = text.match(/(^|[^a-zçğıöşü])nt[\s-]?(\d{4})/);
const baseSubjects = {
  teknik_destek: "ürün arızası bildirimi",
  iade: "iade talebi",
  kargo: "kargo sorunu bildirimi",
  garanti: "garanti talebi",
  genel: "genel destek talebi"
};
let base = isSafety ? "güvenlik riski bildirimi" : baseSubjects[category];
let subject = found.length > 0 ? found.join(" / ") + ": " + base : base.charAt(0).toLocaleUpperCase("tr-TR") + base.slice(1);
if (orderMatch) subject += " (NT" + orderMatch[2] + ")";
subject = subject.slice(0, 80);

return [{ json: {
  message: original,
  subject,
  category,
  priority,
  status: "acik",
  source: "n8n_chat"
} }];

// Data Table'ın döndürdüğü GERÇEK satır id değerinden referans üretir
const row = $input.first().json;
const prep = $('Destek Kaydi Hazirla').first().json;
const rowId = row.id;
const categoryLabels = { teknik_destek: "Teknik destek", iade: "İade", kargo: "Kargo", garanti: "Garanti", genel: "Genel" };
const priorityLabels = { Yuksek: "Yüksek", Orta: "Orta", Normal: "Normal" };
const category = row.category || prep.category;
const priority = row.priority || prep.priority;

let output = "";
if (rowId !== undefined && rowId !== null && rowId !== "") {
  const ref = "NVT-" + String(rowId).padStart(5, "0");
  output = "✅ Destek kaydınız oluşturuldu.\n\nKayıt referansı: " + ref +
    "\nKonu: " + (row.subject || prep.subject) +
    "\nKategori: " + (categoryLabels[category] || category) +
    "\nÖncelik: " + (priorityLabels[priority] || priority) +
    "\nDurum: Açık\n\nMesajınız kayıt tablosuna kaydedildi. " +
    "⚠️ Bu bir eğitim amaçlı DEMO sistemdir; kimseye otomatik bildirim gönderilmedi.";
} else {
  output = "⚠️ Kayıt işlemi tamamlandı gibi görünüyor ancak kayıt numarası alınamadı. Talebinizin kaydedildiğini doğrulayamıyoruz; lütfen tekrar deneyin.";
}

return [{ json: { output } }];

// Yalnızca referans, durum ve kategori gösterilir (mesaj içeriği ve kişisel veri gösterilmez)
const row = $input.first().json;
const asked = $('Mesaji Analiz Et').first().json.ticketId;
const statusLabels = { acik: "Açık", kapali: "Kapalı", islemde: "İşlemde" };
const categoryLabels = { teknik_destek: "Teknik destek", iade: "İade", kargo: "Kargo", garanti: "Garanti", genel: "Genel" };
const priorityLabels = { Yuksek: "Yüksek", Orta: "Orta", Normal: "Normal" };

let output = "";
if (row && row.id !== undefined && row.id !== null) {
  const ref = "NVT-" + String(row.id).padStart(5, "0");
  output = "🔎 Destek kaydı bulundu\n\nReferans: " + ref +
    "\nKonu: " + (row.subject || "Belirtilmemiş") +
    "\nDurum: " + (statusLabels[row.status] || row.status || "Bilinmiyor") +
    "\nKategori: " + (categoryLabels[row.category] || row.category || "Bilinmiyor") +
    "\nÖncelik: " + (priorityLabels[row.priority] || row.priority || "Belirtilmemiş") +
    "\n\n⚠️ Bu bir eğitim amaçlı DEMO sistemdir. Gerçek kullanımda destek kaydı sorgulama için müşteri kimlik doğrulaması zorunlu olacaktır.";
} else {
  output = "❌ NVT-" + String(asked).padStart(5, "0") + " referanslı bir destek kaydı bulunamadı. Lütfen referans numarasını kontrol edip tekrar deneyin.";
}

return [{ json: { output } }];
